import React, {useContext} from 'react'
import Header from '../components/Header'
import { Container, Row } from 'react-bootstrap'
import background from '../images/helping.webp'
import AuthContext from '../components/AuthContext'

function NeedsScreen() {
  const {user}= useContext(AuthContext)
  const fetchData = async () => {
    try {
      const response = await axios.get('http://localhost:8000/api/getallrequest/', {
        headers: {
          'Authorization': `Bearer ${authTokens.access}`,
          'Content-Type': 'application/json'
        }
      });
      setPrevious(response.data.reverse());
    
    } catch (error) {
      console.log('There was a problem: ', error)
    }
  }
  return (
    <>
      <Header/>
      <Container fluid style={{backgroundImage: `url(${background})`, backgroundRepeat: 'no-repeat', backgroundPosition: 'center', backgroundSize: 'cover', height: '100vh', opacity: 0.1}}>

      </Container>
    </>
  )
}

export default NeedsScreen
